#!/bin/bash
# Sets a random wallpaper via awww, plus a blurred copy of the SAME image
# on a second awww-daemon namespace, for use as the Niri overview backdrop.
# Blurred copies are pre-generated by precache-wallpaper-blur.sh, so this
# script normally just looks the cache up instead of processing anything.
set -euo pipefail

WALLPAPER_DIR="$HOME/dotfiles/backgrounds"
BLUR_DIR="$HOME/.cache/wallpaper-blur"
BLUR_NAMESPACE="wallpaper"
BLUR_STRENGTH="0x8"

mkdir -p "$BLUR_DIR"

# --- Pick a random wallpaper -------------------------------------------------
IMAGE=$(find "$WALLPAPER_DIR" -type f | shuf -n 1)
NAME=$(basename "$IMAGE")
BLUR_IMAGE="$BLUR_DIR/${NAME}.png"

sleep 5

# --- Set the normal wallpaper -------------------------------------------------
awww img "$IMAGE" --transition-type random --transition-duration 2

# --- Fallback: generate the blur now if it's missing or stale ---------------
# (e.g. a wallpaper added since the last precache run). Keeps things working
# even if you forget to run the precache script, just slower on that one pick.
if [[ ! -f "$BLUR_IMAGE" || "$IMAGE" -nt "$BLUR_IMAGE" ]]; then
    SRC="$IMAGE"
    [[ "${IMAGE,,}" == *.gif ]] && SRC="${IMAGE}[0]"
    if command -v magick >/dev/null; then
        magick "$SRC" -blur "$BLUR_STRENGTH" "$BLUR_IMAGE"
    else
        convert "$SRC" -blur "$BLUR_STRENGTH" "$BLUR_IMAGE"
    fi
fi

# --- Set the blurred wallpaper on the backdrop namespace ----------------------
awww img "$BLUR_IMAGE" \
    --namespace "$BLUR_NAMESPACE" \
    --transition-type fade \
    --transition-duration 2

notify-send -t 2 "Wallpaper" "Wallpaper has been updated" -i $IMAGE
